// BIOS images in public/roms: the standard miniVIC BIOS first (default), then the KEYB/SD fork
// (extended keyboard, SDSC v1/v2 and SDHC cards, sector read/write for programs).
// List generated by scripts/sync-bios.mjs: do not edit it by hand.

export type BiosId = 'std' | 'keybsd';

export interface RomInfo {
  id: BiosId;
  file: string;
  title: string;
  version: string;
}

export const ROMS: RomInfo[] = [
  { id: 'std', file: 'minivic.bin', title: 'BIOS 24.10.26 (standard)', version: '24.10.26' },
  { id: 'keybsd', file: 'minivic_keybsd.bin', title: 'BIOS 27.10.26 KEYB/SD', version: '27.10.26 KEYB/SD' },
];
